package com.shopapp.media.utils;

/**
 * Display file names: the part after the last path separator, characters other than letters, digits, '.', '-'
 * and '_' replaced by '_', no leading dots, at most 100 characters. The result is safe in a URL path segment and
 * a Content-Disposition header; it never names the stored file (that name is generated by the server).
 */
public final class FileNames {

    static final String DEFAULT_NAME = "image";
    private static final int MAX_LENGTH = 100;

    private FileNames() {
    }

    /**
     * The sanitized display name for the given client-supplied name ({@value #DEFAULT_NAME} when nothing is left).
     */
    public static String sanitize(String name) {
        if (name == null) {
            return DEFAULT_NAME;
        }
        String trimmed = name.trim();
        int lastSeparator = Math.max(trimmed.lastIndexOf('/'), trimmed.lastIndexOf('\\'));
        String base = trimmed.substring(lastSeparator + 1);
        String safe = base.replaceAll("[^A-Za-z0-9._-]", "_");
        if (safe.length() > MAX_LENGTH) {
            // keep the end, which holds the extension
            safe = safe.substring(safe.length() - MAX_LENGTH);
        }
        safe = safe.replaceFirst("^\\.+", "");
        return safe.isEmpty() ? DEFAULT_NAME : safe;
    }
}
